// Data: extras for the Accounting Standards & Financial Reporting portal.
// Glossary, chart of accounts, journal lab, impact lab, cases, interview bank, month-end pack.

export const GLOSSARY = [
  { term: 'Accrual', definition: 'An accounting entry that recognizes revenue earned or expenses incurred in the current period even though the related cash has not yet been received or paid, following the accrual basis of accounting required by the Conceptual Framework.' },
  { term: 'Amortized Cost', definition: 'The measurement of a financial asset or liability at initial recognition minus principal repayments, plus or minus the cumulative amortization of any discount or premium using the effective interest method, and adjusted for any loss allowance (IFRS 9).' },
  { term: 'Asset', definition: 'A present economic resource controlled by the entity as a result of past events, with the potential to produce economic benefits (Conceptual Framework).' },
  { term: 'Balance Sheet', definition: 'The statement of financial position presenting an entity\u2019s assets, liabilities and equity at a point in time, governed by the presentation requirements of IAS 1.' },
  { term: 'Cash Flow', definition: 'The inflows and outflows of cash and cash equivalents during a period, classified into operating, investing and financing activities under IAS 7.' },
  { term: 'CGU', definition: 'Cash-generating unit: the smallest identifiable group of assets that generates cash inflows largely independent of other assets or groups of assets; the level at which goodwill and corporate assets are tested for impairment under IAS 36.' },
  { term: 'Contingent Liability', definition: 'A possible obligation from past events whose existence will be confirmed only by uncertain future events, or a present obligation that is not recognized because an outflow is not probable or cannot be reliably measured (IAS 37); it is disclosed, not recognized.' },
  { term: 'Credit Impaired', definition: 'A financial asset is credit-impaired (Stage 3) when one or more events with a detrimental impact on its estimated future cash flows have occurred, such as significant financial difficulty of the borrower or a breach of contract (IFRS 9).' },
  { term: 'Current Asset', definition: 'An asset expected to be realized, sold or consumed within the entity\u2019s normal operating cycle or within twelve months of the reporting date (IAS 1).' },
  { term: 'Deferred Tax', definition: 'Tax payable or recoverable in future periods arising from temporary differences between the carrying amounts of assets and liabilities and their tax bases, recognized under IAS 12 using the balance-sheet liability method.' },
  { term: 'Depreciation', definition: 'The systematic allocation of the depreciable amount of property, plant and equipment over its useful life (IAS 16); it is a cost-allocation process, not a valuation exercise.' },
  { term: 'EBITDA', definition: 'Earnings before interest, tax, depreciation and amortization; a non-GAAP performance measure used to assess operating profitability before financing, tax and non-cash charges.' },
  { term: 'ECL', definition: 'Expected credit losses: the probability-weighted average of credit losses, with the respective risks of default as the weights. IFRS 9 requires a 12-month ECL allowance for Stage 1 assets and lifetime ECL for Stage 2 and Stage 3 assets.' },
  { term: 'Effective Interest Rate', definition: 'The rate that exactly discounts estimated future cash receipts or payments through the expected life of a financial instrument to its gross carrying amount (for assets) or amortized cost (for liabilities) (IFRS 9).' },
  { term: 'Equity', definition: 'The residual interest in the assets of an entity after deducting all its liabilities (Conceptual Framework).' },
  { term: 'Fair Value', definition: 'The price that would be received to sell an asset or paid to transfer a liability in an orderly transaction between market participants at the measurement date (IFRS 13).' },
  { term: 'FVOCI', definition: 'Fair value through other comprehensive income: a measurement category for financial assets where fair value changes are recognized in OCI, with only interest, impairment and foreign exchange gains or losses recognized in profit or loss for debt instruments (IFRS 9).' },
  { term: 'FVTPL', definition: 'Fair value through profit or loss: a measurement category where all fair value changes on a financial asset or liability are recognized in profit or loss (IFRS 9).' },
  { term: 'Going Concern', definition: 'The assumption that the entity will continue in operation for the foreseeable future (at least twelve months from the reporting date), underpinning the preparation of financial statements on a non-liquidation basis (IAS 1).' },
  { term: 'Goodwill', definition: 'The excess of the consideration transferred (plus any non-controlling interest and the fair value of any previous equity interest) over the fair value of the identifiable net assets acquired in a business combination (IFRS 3); it is not amortized and impairment losses on goodwill are never reversed.' },
  { term: 'Gross Margin', definition: 'Revenue minus cost of sales, expressed as an amount or as a percentage of revenue; it measures production and pricing profitability before operating expenses.' },
  { term: 'IAS', definition: 'International Accounting Standards: the older series of standards issued by the IASC, many still in force (for example IAS 16 and IAS 37), now maintained by the IASB alongside IFRS.' },
  { term: 'IFRS', definition: 'International Financial Reporting Standards: the set of accounting standards issued by the IASB that prescribe recognition, measurement, presentation and disclosure in general-purpose financial statements.' },
  { term: 'Impairment', definition: 'A loss recognized when an asset\u2019s carrying amount exceeds its recoverable amount (IAS 36); for financial assets, impairment is measured through expected credit losses under IFRS 9.' },
  { term: 'Liability', definition: 'A present obligation of the entity to transfer an economic resource as a result of past events (Conceptual Framework).' },
  { term: 'Materiality', definition: 'Information is material if omitting, misstating or obscuring it could reasonably be expected to influence the decisions of the primary users of the financial statements (IAS 1 and the Conceptual Framework).' },
  { term: 'NCI', definition: 'Non-controlling interest: the equity in a subsidiary not attributable, directly or indirectly, to the parent; presented separately within consolidated equity (IFRS 10).' },
  { term: 'Net Realizable Value', definition: 'The estimated selling price in the ordinary course of business less the estimated costs of completion and the estimated costs necessary to make the sale (IAS 2); inventory is measured at the lower of cost and net realizable value.' },
  { term: 'Provision', definition: 'A liability of uncertain timing or amount, recognized when there is a present obligation from a past event, an outflow of resources is probable, and a reliable estimate can be made (IAS 37).' },
  { term: 'Revenue', definition: 'Income arising in the ordinary course of an entity\u2019s activities, recognized under IFRS 15 when (or as) the entity satisfies a performance obligation by transferring a promised good or service to the customer.' },
  { term: 'Right-of-Use Asset', definition: 'The lessee\u2019s asset representing its right to use an underlying asset over the lease term, initially measured at cost including the initial lease liability (IFRS 16) and subsequently depreciated.' },
  { term: 'SICR', definition: 'Significant increase in credit risk: the trigger that moves a financial instrument from Stage 1 (12-month ECL) to Stage 2 (lifetime ECL) under IFRS 9, assessed by comparing the risk of default at the reporting date with that at initial recognition.' },
  { term: 'Stage 1', definition: 'Performing financial assets with no significant increase in credit risk since initial recognition: a 12-month expected credit loss allowance is recognized and interest is calculated on the gross carrying amount (IFRS 9).' },
  { term: 'Stage 2', definition: 'Financial assets with a significant increase in credit risk since initial recognition but not yet credit-impaired: lifetime expected credit losses are recognized while interest is still calculated on the gross carrying amount (IFRS 9).' },
  { term: 'Stage 3', definition: 'Credit-impaired financial assets: lifetime expected credit losses are recognized and interest revenue is calculated on the net carrying amount, that is, after deducting the loss allowance (IFRS 9).' },
  { term: 'Working Capital', definition: 'Current assets minus current liabilities; a measure of short-term liquidity and of the operating capital tied up in the business cycle.' },
  { term: 'Carrying Amount', definition: 'The amount at which an asset or liability is recognized in the statement of financial position, after deducting accumulated depreciation, amortization or impairment and any loss allowance.' },
  { term: 'Closing Rate', definition: 'The spot exchange rate at the end of the reporting period, used under IAS 21 to remeasure monetary assets and liabilities denominated in a foreign currency.' },
  { term: 'Control', definition: 'An investor controls an investee when it has power over the investee, exposure or rights to variable returns, and the ability to use its power to affect those returns (IFRS 10); control triggers full consolidation.' },
  { term: 'Cutoff', definition: 'The principle that transactions are recorded in the correct accounting period, so that revenue, expenses, assets and liabilities are recognized when the underlying event occurs rather than when cash moves.' },
  { term: 'Double-Entry Bookkeeping', definition: 'The system in which every transaction is recorded with equal debits and credits, keeping the accounting equation (assets = liabilities + equity) in balance at all times.' },
  { term: 'Financial Asset', definition: 'Cash, an equity instrument of another entity, or a contractual right to receive cash or another financial asset (IFRS 9); its classification depends on the entity\u2019s business model and the SPPI (solely payments of principal and interest) test.' },
  { term: 'Functional Currency', definition: 'The currency of the primary economic environment in which the entity operates; foreign-currency transactions are measured by translating them into the functional currency under IAS 21.' },
  { term: 'Journal Entry', definition: 'The formal record of a transaction in the general journal, specifying the accounts debited and credited and the amounts; journal entries are the building blocks of double-entry bookkeeping.' },
  { term: 'Lease Liability', definition: 'The lessee\u2019s obligation to make lease payments, measured at the present value of future payments discounted at the interest rate implicit in the lease or, if that cannot be determined, the incremental borrowing rate (IFRS 16).' },
  { term: 'Matching Principle', definition: 'The concept that expenses are recognized in the same period as the related revenue they helped to generate, supporting a faithful measurement of periodic performance.' },
  { term: 'Present Value', definition: 'The current worth of a future sum of money or stream of cash flows, discounted at an appropriate rate to reflect the time value of money; the basis for measuring lease liabilities, provisions and value in use.' },
  { term: 'Recoverable Amount', definition: 'The higher of an asset\u2019s (or CGU\u2019s) fair value less costs of disposal and its value in use; the benchmark against which the carrying amount is compared in impairment testing (IAS 36).' },
  { term: 'Retrospective Application', definition: 'Applying a new accounting policy or correcting a prior-period error as if it had always applied, with restatement of comparative information (IAS 8).' },
  { term: 'Subsidiary', definition: 'An entity controlled by another entity (the parent); its financial statements are consolidated line by line with the parent\u2019s (IFRS 10).' },
  { term: 'Trial Balance', definition: 'A list of all general ledger account balances at a point in time, used to verify that total debits equal total credits before the financial statements are prepared.' },
  { term: 'Value in Use', definition: 'The present value of the future cash flows expected to be derived from an asset or cash-generating unit; one of the two measures used to determine recoverable amount under IAS 36.' },
];

